let gardenSelected=null,gardenMode='day';
function ensureGarden(){if(state.garden)return;state.garden={night:false,items:state.decorSlots.map((id,i)=>({uid:'legacy'+i,id,x:28+i*20,y:70,scale:1,angle:0})).filter(o=>o.id!=='none'&&state.decorOwned.includes(o.id)),next:1,plants:[null,null,null],berries:0,visits:[]};save()}
function gardenAdd(id){ensureGarden();if(!state.decorOwned.includes(id)||state.garden.items.length>=24)return false;const uid='g'+state.garden.next++;state.garden.items.push({uid,id,x:40+Math.random()*20,y:55+Math.random()*15,scale:1,angle:0});save();return uid}
function gardenUpdate(uid,patch){const o=state.garden.items.find(o=>o.uid===uid);if(!o)return false;for(const [k,min,max] of [['x',8,92],['y',30,86],['scale',.65,1.5],['angle',-180,180]])if(Number.isFinite(patch[k]))o[k]=Math.min(max,Math.max(min,patch[k]));save();return true}
function gardenRemove(uid){state.garden.items=state.garden.items.filter(o=>o.uid!==uid);save()}
function plantBed(i){ensureGarden();if(!Number.isInteger(i)||i<0||i>2)return false;const p=state.garden.plants[i];if(!p){state.garden.plants[i]={at:Date.now(),watered:false};save();return 'planted'}if(!p.watered){p.watered=true;save();return 'watered'}if(Date.now()-p.at>=60000){state.garden.berries+=3;state.garden.plants[i]=null;save();return 'harvested'}return false}
function feedGarden(){if(state.garden.berries<1)return false;state.garden.berries--;state.bond=Math.min(100,state.bond+3);save();return true}
function gardenArt(id){const wrap=s=>`<svg viewBox="0 0 120 110" aria-hidden="true">${s}</svg>`;const petals=(x,y)=>`<g transform="translate(${x} ${y})"><path d="M0 0V25" stroke="#537745" stroke-width="3"/><g fill="#fff3c8"><ellipse cy="-9" rx="6" ry="10"/><ellipse cy="9" rx="6" ry="10"/><ellipse cx="-9" rx="10" ry="6"/><ellipse cx="9" rx="10" ry="6"/></g><circle r="5" fill="#e2b552"/></g>`;return wrap(({flowers:petals(33,50)+petals(62,34)+petals(86,59),house:'<path d="M29 53H91V99H29Z" fill="#f4dfb6"/><path d="M12 54Q22 8 60 10Q100 12 110 54Q60 72 12 54" fill="#c77e68" stroke="#a66351" stroke-width="2"/><g fill="#fff0cc"><ellipse cx="39" cy="35" rx="10" ry="6"/><ellipse cx="73" cy="24" rx="8" ry="5"/><ellipse cx="90" cy="47" rx="8" ry="5"/></g><path d="M48 100V77Q60 61 72 77V100" fill="#806449"/><circle cx="65" cy="84" r="2" fill="#f4d67e"/><circle cx="37" cy="77" r="6" fill="#b7d6ce"/>',pond:'<ellipse cx="60" cy="71" rx="56" ry="30" fill="#769b70"/><ellipse cx="60" cy="67" rx="49" ry="23" fill="#8dc0b9"/><path d="M24 68Q60 51 96 67M35 80Q62 71 84 79" fill="none" stroke="#d7efe1" stroke-width="2"/><ellipse cx="45" cy="65" rx="15" ry="6" fill="#6f9b5c"/>',cushion:'<ellipse cx="60" cy="74" rx="47" ry="23" fill="#6f9357"/><ellipse cx="60" cy="66" rx="46" ry="22" fill="#9cb979"/><path d="M28 62Q56 46 87 64" fill="none" stroke="#c4d99d" stroke-width="3"/>',lantern:'<path d="M62 100V22Q63 9 79 16" fill="none" stroke="#745a40" stroke-width="5"/><path d="M78 15V31" stroke="#745a40" stroke-width="3"/><rect x="60" y="31" width="35" height="44" rx="10" fill="#f9dc8d" stroke="#a88848" stroke-width="3"/><circle cx="77" cy="52" r="12" fill="#fff3a9"/><path d="M77 40V64M66 52H88" stroke="#fffbe3" stroke-width="3"/>',crystal:'<path d="M60 18L88 52 60 92 32 52Z" fill="#9bcfc0" stroke="#568b80" stroke-width="2"/><path d="M60 18L60 92 45 51Z" fill="#d2f0d6"/><ellipse cx="60" cy="96" rx="35" ry="6" fill="#91ad75"/>',trophy:'<path d="M32 25H88L82 60Q60 85 38 60Z" fill="#e8c86b"/><path d="M34 31H20Q15 60 42 60M86 31H100Q105 60 78 60" fill="none" stroke="#c6a34e" stroke-width="6"/><path d="M60 72V94M39 98H81" stroke="#c6a34e" stroke-width="9"/><path d="M60 36L64 46 75 47 67 54 70 65 60 59 50 65 53 54 45 47 56 46Z" fill="#fff0ac"/>'})[id]||(typeof extraGardenArt!=='undefined'&&extraGardenArt[id])||'')}
function gardenBackdrop(){return `<svg class="gardenBackdrop" viewBox="0 0 1000 600" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="gardenSky" x2="0" y2="1"><stop stop-color="#bedac8"/><stop offset="1" stop-color="#e7ebc7"/></linearGradient></defs><rect width="1000" height="600" fill="url(#gardenSky)"/><circle cx="780" cy="100" r="48" fill="#f8e8a4"/><path d="M0 200Q150 120 300 210T600 180T1000 195V600H0" fill="#91b587"/><path d="M0 290Q250 180 500 270T1000 260V600H0" fill="#b5c997"/><path d="M540 600Q460 440 680 350Q795 310 770 220" fill="none" stroke="#ddd4aa" stroke-width="55"/><ellipse cx="235" cy="390" rx="170" ry="85" fill="#7d9f6d"/><ellipse cx="235" cy="380" rx="157" ry="70" fill="#8bc0b4"/><g fill="none" stroke="#cbe8d2" stroke-width="3"><path d="M105 380Q230 342 370 375M150 410Q230 389 315 411"/></g><g fill="#67945a"><ellipse cx="153" cy="368" rx="29" ry="12"/><ellipse cx="305" cy="398" rx="35" ry="14"/></g><path d="M350 367Q400 322 454 366" fill="none" stroke="#a88d62" stroke-width="20"/><path d="M350 345Q400 300 454 344" fill="none" stroke="#8d7451" stroke-width="5"/><path d="M350 345V370M454 344V370" stroke="#8d7451" stroke-width="6"/><g fill="#658e61"><circle cx="35" cy="110" r="110"/><circle cx="160" cy="30" r="95"/><circle cx="970" cy="120" r="110"/><circle cx="880" cy="30" r="95"/></g><path d="M22 240Q55 130 20 0M973 230Q936 120 980 0" fill="none" stroke="#7a8050" stroke-width="25"/><g fill="#e9e8b3"><circle cx="80" cy="500" r="5"/><circle cx="830" cy="440" r="5"/><circle cx="720" cy="510" r="6"/><circle cx="410" cy="520" r="4"/></g></svg>`}
function renderHome(){ensureGarden();const g=state.garden;$('#content').innerHTML=`<div class="sectionHead"><div><div class="eyebrow">ER LILLA PLATS I ÄLVVÄRLDEN</div><h2>Den förtrollade gläntan</h2></div><button class="outline gardenTime" id="gardenTime">${g.night?'☀ Morgonljus':'☾ Skymning'}</button></div><button class="outline" id="toVillage">Stigen till Älvbyn →</button><p class="gardenLead">En damm att vila vid. Ett hem att göra till ert. Välkommen hem, ${escapeText(state.frogName)}.</p><section id="gardenCanvas" class="gardenCanvas ${g.night?'night':''}" aria-label="Sagoträdgård. Välj ett föremål och använd piltangenterna eller dra för att flytta det.">${gardenBackdrop()}<div class="gardenCottage">${gardenArt('house')}</div>${typeof trollGardenHTML==='function'?trollGardenHTML():''}${typeof seasonOverlayHTML==='function'?seasonOverlayHTML():''}<div class="gardenFireflies" aria-hidden="true">${Array.from({length:12},(_,i)=>`<i style="left:${12+i*7}%;top:${32+(i%4)*12}%;animation-delay:${i*.3}s"></i>`).join('')}</div>${g.items.map(o=>gardenItemHTML(o)).join('')}<button id="gardenFrog" aria-label="Hälsa på ${escapeText(state.frogName)}">${frog()}</button><span class="gardenSign">Gläntan · ${escapeText(state.frogName)}</span></section><div class="gardenEditor"><p id="gardenHint" role="status">Välj en sak i trädgården. Dra den dit du vill eller flytta med piltangenterna.</p><div class="gardenTools"><button class="outline" data-adjust="smaller">− Mindre</button><button class="outline" data-adjust="bigger">+ Större</button><button class="outline" data-adjust="turn">↻ Vrid</button><button class="outline" id="gardenRemove">Till samlingen</button></div></div><div class="gardenLower"><section class="editor"><h3>Din samling</h3><p>Tryck på Placera, välj sedan en plats. Upp till 24 saker kan stå i trädgården.</p><div class="gardenInventory">${decorations.map(d=>{const own=state.decorOwned.includes(d.id);return `<article><div class="gardenThumb">${gardenArt(d.id)}</div><strong>${d.name}</strong>${own?`<button class="outline" data-place="${d.id}" ${g.items.length>=24?'disabled':''}>Placera</button>`:d.cost!==undefined?`<button class="outline" data-buy-garden="${d.id}" ${state.coins<d.cost?'disabled':''}>Köp · ${d.cost} ✦</button>`:`<small>${d.from?d.from:d.cup?'Vinn mästerskapet':d.festival&&typeof seasons!=='undefined'?'Gåva från '+seasons[d.festival].festival.name:'Gåva från äventyr'}</small>`}</article>`}).join('')}</div></section><section class="editor gardenLife"><h3>Trädgårdens lilla skafferi</h3><p>Plantera, vattna och skörda bär. De mognar på en minut och vissnar aldrig.</p><div class="gardenBeds">${g.plants.map((p,i)=>`<button class="outline" data-bed="${i}">${!p?'✿ Plantera bär':!p.watered?'💧 Vattna':Date.now()-p.at>=60000?'🍓 Skörda 3 bär':'🌱 Växer – kontrollera'}<small>Odlingsbädd ${i+1}</small></button>`).join('')}</div><p>🍓 ${g.berries} bär i korgen</p><button class="primary" id="gardenFeed" ${g.berries<1?'disabled':''}>Bjud grodan på ett bär</button><h3>Besök i gläntan</h3><p>Astrid kommer gärna förbi för en lugn stund bland blommorna.</p><button class="outline" id="inviteAstrid">Bjud in Astrid</button><div id="gardenVisitor" role="status"></div></section></div>`;wireGarden();}
function gardenItemHTML(o){const d=decorations.find(d=>d.id===o.id);return `<button class="gardenItem ${o.uid===gardenSelected?'selected':''}" data-garden-item="${o.uid}" aria-label="${d.name}, flytta med piltangenter eller dra" style="left:${o.x}%;top:${o.y}%;--size:${o.scale};--angle:${o.angle}deg;z-index:${Math.round(o.y)}">${gardenArt(o.id)}</button>`}
function wireGarden(){$('#toVillage').onclick=()=>{tab='village';render()};const canvas=$('#gardenCanvas');function select(uid){gardenSelected=uid;document.querySelectorAll('[data-garden-item]').forEach(e=>e.classList.toggle('selected',e.dataset.gardenItem===uid));const o=state.garden.items.find(o=>o.uid===uid);$('#gardenHint').textContent=o?decorations.find(d=>d.id===o.id).name+' är vald. Dra eller använd piltangenterna.':'Välj en sak att flytta.';document.querySelectorAll('[data-adjust],#gardenRemove').forEach(b=>b.disabled=!o)}function refreshItem(o,e){e.style.left=o.x+'%';e.style.top=o.y+'%';e.style.setProperty('--size',o.scale);e.style.setProperty('--angle',o.angle+'deg');e.style.zIndex=Math.round(o.y)}document.querySelectorAll('[data-garden-item]').forEach(e=>{let drag=null;e.onclick=()=>select(e.dataset.gardenItem);e.onpointerdown=ev=>{if(ev.button!==0)return;const o=state.garden.items.find(o=>o.uid===e.dataset.gardenItem),rect=canvas.getBoundingClientRect();select(o.uid);drag={px:ev.clientX,py:ev.clientY,x:o.x,y:o.y,rect};e.setPointerCapture(ev.pointerId)};e.onpointermove=ev=>{if(!drag)return;const o=state.garden.items.find(o=>o.uid===e.dataset.gardenItem);o.x=Math.min(92,Math.max(8,drag.x+(ev.clientX-drag.px)/drag.rect.width*100));o.y=Math.min(86,Math.max(30,drag.y+(ev.clientY-drag.py)/drag.rect.height*100));refreshItem(o,e)};e.onpointerup=e.onpointercancel=()=>{if(drag){drag=null;save()}};e.onkeydown=ev=>{const dir={ArrowLeft:[-2,0],ArrowRight:[2,0],ArrowUp:[0,-2],ArrowDown:[0,2]}[ev.key];if(!dir)return;ev.preventDefault();select(e.dataset.gardenItem);const o=state.garden.items.find(o=>o.uid===gardenSelected);gardenUpdate(o.uid,{x:o.x+dir[0],y:o.y+dir[1]});refreshItem(o,e)}});select(gardenSelected);document.querySelectorAll('[data-adjust]').forEach(b=>b.onclick=()=>{const o=state.garden.items.find(o=>o.uid===gardenSelected);if(!o)return;gardenUpdate(o.uid,b.dataset.adjust==='turn'?{angle:o.angle>=180?-180:o.angle+15}:{scale:o.scale+(b.dataset.adjust==='bigger'?.1:-.1)});refreshItem(o,document.querySelector(`[data-garden-item="${o.uid}"]`))});$('#gardenRemove').onclick=()=>{gardenRemove(gardenSelected);gardenSelected=null;renderHome()};document.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>{gardenSelected=gardenAdd(b.dataset.place);renderHome()});document.querySelectorAll('[data-buy-garden]').forEach(b=>b.onclick=()=>{if(buyDecoration(b.dataset.buyGarden)){sidebar();renderHome()}});if($('.gardenCottage'))$('.gardenCottage').onclick=()=>{tab='house';render()};if($('#gardenTroll'))$('#gardenTroll').onclick=()=>{tab='fish';render()};$('#gardenTime').onclick=()=>{state.garden.night=!state.garden.night;save();renderHome()};$('#gardenFrog').onclick=()=>{toast(state.personality==='Sömnig'?'Din groda gäspar nöjt i mossan.':'Din groda hälsar med ett glatt skutt!')};document.querySelectorAll('[data-bed]').forEach(b=>b.onclick=()=>{const result=plantBed(+b.dataset.bed);renderHome();toast(result==='harvested'?'Tre bär i korgen!':result==='watered'?'Vattnat! Bären mognar en minut efter plantering.':result==='planted'?'Bären är planterade. Nu behöver de vatten.':'Bären växer fortfarande. Kom tillbaka om en liten stund.')});$('#gardenFeed').onclick=()=>{if(feedGarden()){renderHome();toast('Mums! +3 vänskap.')}};$('#inviteAstrid').onclick=()=>{$('#gardenVisitor').innerHTML='<img src="assets/astrid-portrait.webp" alt="Astrid besöker gläntan"><p>”Vilken fin plats ni har skapat! Här kan både små grodor och stora drömmar vila.”</p>';if(!state.garden.visits.includes('astrid')){state.garden.visits.push('astrid');save()}}}
